var z = '-^@^';

var NX = [6912847, 367, 20411, 613, 43759, 5019283];
var SX = [5283741, 241, 41953, 187, 56129, 4738901];

function spin(src, c) {
  var out = [];
  var k = 0;
  var z = c[0];
  var len;
  var p;
  var q;
  var i;
  var j;
  var tmp;
  while (k < src.length) {
    out[k] = src.charAt(k);
    k += 1;
  }
  len = out.length;
  k = 0;
  while (k < len) {
    p = z * (k + c[1]) + (z % c[2]);
    q = z * (k + c[3]) + (z % c[4]);
    i = p % len;
    j = q % len;
    tmp = out[i];
    out[i] = out[j];
    out[j] = tmp;
    z = (p + q) % c[5];
    k += 1;
  }
  return out.join('');
}

function splitLane(blob) {
  var mark = String.fromCharCode(28);
  var text = spin(blob, NX);
  text = text.split('^').join(mark);
  text = text.split('*1').join('^');
  text = text.split('*0').join('*');
  return text.split(mark);
}

function peel(blob) {
  return spin(blob, SX);
}
